#include "symrep_bootstrap.hpp"
#include "tensor_kernel.hpp"
using namespace symrep;
int main(int argc,char**argv){try{
 require(argc==2,"output directory required");fs::path out=argv[1];rref_option_t opt;opt->pool.reset(1);
 Mat f(2,4),c(2,4);std::array<long,8> fn{1,2,-3,5,2,-1,4,3},fd{2,3,5,7,11,13,17,19},cn{2,-1,3,1,-2,5,1,-4},cd{3,5,7,11,13,17,19,23};
 for(size_t b=0;b<2;++b)for(size_t z=0;z<4;++z){f[b].push_back(index(z),Q(fn[b*4+z])/Q(fd[b*4+z]));c[b].push_back(index(z),Q(cn[b*4+z])/Q(cd[b*4+z]));}
 MatrixTensorView fv(f,{2,2,2});write_tensor_view(out/"affine_scaling_fixture_input.wxf",fv);auto ft=read(out/"affine_scaling_fixture_input.wxf");Mat a(4,5),h(2,2);std::array<long,4>x{1,2,-1,3};
 for(size_t o=0;o<2;++o)for(size_t q=0;q<2;++q){Q rhs=0;for(size_t b=0;b<2;++b)for(size_t j=0;j<2;++j){Q v=0;for(size_t l=0;l<2;++l)v+=*f[b].find(index(o*2+l))*(*c[q].find(index(l*2+j)));a[o*2+q].push_back(index(b*2+j),v);rhs-=v*Q(x[b*2+j]);}a[o*2+q].push_back(4,rhs);h[o].push_back(index(q),rhs);}
 tensor_kernel::AffineConstraintRows source(ft,c,2,h);structured_kernel::Relations rel(5);Mat exact(0,5);source(rel,SIZE_MAX,[&](Vec&&r){exact.rows.push_back(std::move(r));});exact.nrow=exact.rows.size();require(exact.nrow==4,"exact scan row count");
 for(size_t r=0;r<4;++r){Q scale=exact[r][0]/a[r][0];for(size_t z=0;z<5;++z)require(*exact[r].find(index(z))==scale*(*a[r].find(index(z))),"rational equation scaling mismatch");}
 const ulong prime=2305843009213693951UL;field_t fp(FIELD_Fp,prime);std::vector<I>cols{0,1,2,3,4};using MM=sparse_mat<ulong,I>;using MV=sparse_vec<ulong,I>;MM modular(0,5);source.modular(rel,cols,fp,[&](MV&&r){modular.rows.push_back(std::move(r));});modular.nrow=modular.rows.size();auto expected=exact%fp.mod;require(modular.nrow==4,"modular row count");for(size_t r=0;r<4;++r){require(modular[r].nnz()==expected[r].nnz(),"modular support");for(size_t p=0;p<modular[r].nnz();++p)require(modular[r](p)==expected[r](p)&&modular[r][p]==expected[r][p],"modular alpha or scaling");}
 Mat point(1,5);for(size_t z=0;z<4;++z)point[0].push_back(index(z),Q(x[z]));point[0].push_back(4,Q(1));size_t nonzero=0;source.residual(point%fp.mod,fp,0,[&](MV&&r){nonzero+=r.nnz();},nullptr);require(!nonzero,"full affine residual on exact point");
 Mat id(5,5);for(size_t z=0;z<5;++z)id[z].push_back(index(z),Q(1));MM residual(0,5);source.residual(id%fp.mod,fp,0,[&](MV&&r){residual.rows.push_back(std::move(r));},nullptr);residual.nrow=residual.rows.size();require(residual.nrow==4,"full residual count");for(size_t r=0;r<4;++r)for(size_t p=0;p<expected[r].nnz();++p)require(*residual[r].find(expected[r](p))==expected[r][p],"full residual must include affine coordinate");
 auto bound=source.integral_residual_bound(id);for(const auto&r:exact.rows){int_t den=1;for(auto[z,v]:r)den=LCM(den,v.den());for(auto[z,v]:r){Q y=v*Q(den);require(y.is_integer()&&y.num().abs()<=bound,"denominator-aware height bound");}}
 size_t guards=0;try{std::ostringstream os;source.profile(rel,os);}catch(const std::logic_error&){++guards;}try{source.verify(point,opt);}catch(const std::logic_error&){++guards;}require(guards==2,"unused API guards");
 auto k=kernel(a,opt);require(k.nrow==1,"reference kernel dimension");require(mul(a,transpose(point)).nnz()==0,"direct affine point");std::ofstream j(out/"affine_scaling_fixture.json");j<<"{\"pass\":true,\"reference_equations\":4,\"coordinates_including_alpha\":5,\"reference_kernel_dimension\":1,\"nonunit_prefix_local_and_rhs_denominators\":true,\"exact_row_scaling\":true,\"modular_discovery_includes_alpha\":true,\"full_residual_includes_alpha\":true,\"denominator_height_bound\":true,\"guarded_unused_methods\":2,\"physical_data_read\":false}\n";std::cout<<"PASS affine rational scaling and full residual fixture\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
